//! BQ086: existing death waves, complete pre-response targets, real sacrifice/sealing.
use crate::{catalog,engine::RuleResult,model::*,rules::*,black_next20::BlackDeathObservation};
use std::collections::BTreeSet;
pub(crate) const ID:&str="BQ086";
pub(crate) const DEATH:&str="bq086-friendly-death";
pub(crate) const ENTRY:&str="bq086-entry-seal-corpse";
const SACRIFICE:&str="bq086-sacrifice";
fn same<T:serde::Serialize>(a:&T,b:&T)->bool{serde_json::to_value(a).unwrap()==serde_json::to_value(b).unwrap()}
fn owns(ops:&[Op])->bool{ops.iter().any(|o|match o{Op::BQ086Death{..}|Op::BQ086Seal=>true,Op::ForEachLivingPlayer(v)|Op::ForEachLivingPlayerFromActor(v)=>owns(v),Op::IfTargetExhausted{exhausted,ready,..}=>owns(std::slice::from_ref(exhausted))||owns(std::slice::from_ref(ready)),_=>false})}
pub(crate) fn related(a:&AbilitySpec)->bool{a.key.starts_with("bq086-")||a.event==Some(Event::BQ086Death)||owns(&a.ops)||a.modes.iter().any(|m|owns(&m.ops))||a.targets.iter().any(|t|t.predicate==Some(TargetPredicate::BQ086Corpse))}
fn frame_related(f:&ResolutionFrame)->bool{f.ability_key.starts_with("bq086-")||f.steps.iter().any(|s|owns(std::slice::from_ref(&s.op)))}
pub(crate) fn definition()->Definition{
 let enemy=target(Zone::Player,EntityKind::Any,Relation::EnemyTeam,Range::Anywhere);
 let mut corpse=target(Zone::Graveyard,EntityKind::Any,Relation::OwnedByActor,Range::Anywhere);corpse.predicate=Some(TargetPredicate::BQ086Corpse);
 let mut host=target(Zone::Board,EntityKind::Attachment,Relation::ControlledByActor,Range::Anywhere);host.subtype=Some("研究".into());
 let mut d=with_abilities(vec![ability(DEATH,"本方角色死亡：目标敌方玩家牺牲角色或暗藏者",Timing::Fast,vec![],vec![enemy],vec![Op::BQ086Death{observation:None}],Some(Event::BQ086Death)),ability(ENTRY,"进场：将本人墓地目标无名尸体封印在目标本方研究附属上",Timing::Fast,vec![],vec![corpse,host],vec![Op::BQ086Seal],Some(Event::Enter))]);d.traits.wound=1;d
}
pub(crate) fn validate_ability(id:&str,a:&AbilitySpec)->RuleResult<()>{let mut expected=definition().abilities.into_iter().find(|v|v.key==a.key).ok_or("BQ086没有该能力")?;if let [Op::BQ086Death{observation}]=a.ops.as_slice(){expected.ops=vec![Op::BQ086Death{observation:observation.clone()}];}if id!=ID||!same(a,&expected){return Err("BQ086必须保留完整原能力及双目标".into());}Ok(())}
pub(crate) fn validate_definition(id:&str,d:&Definition)->RuleResult<()>{if (id==ID||d.abilities.iter().any(related))&&(id!=ID||!same(d,&definition())){return Err("BQ086完整印刷规则不可增删或移植".into());}Ok(())}
pub(crate) fn validate_action(id:&str,a:&Action)->RuleResult<()>{if id!=ID{return Ok(());}let expected=match a.kind.as_str(){"deploy"|"conceal"=>Action{card_id:a.card_id.clone(),region:a.region,..Action::new(&a.kind)},"reveal"=>Action{card_id:a.card_id.clone(),..Action::new("reveal")},_=>return Err("BQ086没有主动发动印刷触发的入口".into())};if *a!=expected{return Err("BQ086角色操作不能夹带目标或额外载荷".into());}Ok(())}
pub(crate) fn validate_choice(p:&Pending,a:&Action)->RuleResult<()>{let ours=match &p.resolution{ChoiceResolution::Declare{declaration,stage}=>related(&declaration.ability)||matches!(stage,DeclareChoice::BQ086Host{..}),ChoiceResolution::Frame{frame,choice}=>frame_related(frame)||matches!(choice,FrameChoice::BQ086Sacrifice),_=>false};if ours&&*a!=(Action{choice_id:a.choice_id.clone(),selected:a.selected.clone(),..Action::new("choose")}){return Err("BQ086选择只能提交原选项".into());}Ok(())}
impl Game{
 pub(crate) fn bq086_sources(&self)->Vec<SourceSnapshot>{self.regions.iter().enumerate().filter(|(_,r)|!r.vacant).flat_map(|(r,v)|v.cards.iter().map(move|c|(r,c))).filter(|(_,c)|c.definition==ID&&!c.face_down&&!self.players[c.controller].eliminated).map(|(r,c)|self.source_snapshot(c,Some(r))).collect()}
 pub(crate) fn bq086_observe(&mut self,sources:&[SourceSnapshot],o:&BlackDeathObservation){for source in sources{if source.card.controller!=o.dead.controller{continue;}let mut a=definition().abilities.remove(0);a.ops=vec![Op::BQ086Death{observation:Some(o.clone())}];self.effects.push_back(Effect::Declare{declaration:Declaration{actor:source.card.controller,source:source.clone(),ability:a}});}}
 pub(crate) fn bq086_corpse(&self,actor:usize,source:&SourceSnapshot,c:&Card)->bool{source.card.definition==ID&&!c.face_down&&c.owner==self.bq095_reference_seat(&source.card)&&catalog::card(&c.definition).name=="无名尸体"&&self.bq095_reference_cards(&source.card).iter().any(|v|v==c)}
 fn bq086_source(&self,actor:usize,s:&SourceSnapshot)->RuleResult<()>{let c=&s.card;if actor>=self.players.len()||c.owner>=self.players.len()||c.controller!=actor||c.definition!=ID||c.face_down||!self.mystic_instance_valid(&c.id)||s.region.is_none_or(|r|r>=self.regions.len())||s.source_region_instance.as_deref().is_none_or(|id|!self.mystic_instance_valid(id)||id==c.id)||s.play_source.is_some()||s.attachment_host_instance.is_some()||s.death_echo.is_some()||s.observed_death.is_some()||s.observed_exposure.is_some()||s.observed_mobility_grant.is_some(){return Err("BQ086原来源、地区或行动者无效".into());}self.mobility_immutable_identity(c)}
 fn bq086_observation(&self,actor:usize,ops:&[Op])->RuleResult<()>{let [Op::BQ086Death{observation:Some(o)}]=ops else{return Err("BQ086死亡触发缺真实波次观察".into());};let c=&o.dead;if o.turn!=self.turn||c.owner>=self.players.len()||c.controller>=self.players.len()||c.face_down||!catalog::catalog().cards.iter().any(|d|d.id==c.definition&&d.kind=="character")||actor!=c.controller||!self.mystic_instance_valid(&c.id)||!self.mystic_instance_number(&o.event_id).zip(self.mystic_instance_number(&c.id)).is_some_and(|(event,dead)|event>dead)||o.region>=self.regions.len()||!self.mystic_instance_valid(&o.region_instance){return Err("BQ086死亡观察必须是当回合本方正面角色".into());}self.mobility_immutable_identity(c)}
 pub(crate) fn validate_bq086_declaration(&self,d:&Declaration)->RuleResult<()>{if !related(&d.ability){return Ok(());}self.bq086_source(d.actor,&d.source)?;validate_ability(&d.source.card.definition,&d.ability)?;if d.ability.key==DEATH{self.bq086_observation(d.actor,&d.ability.ops)?;}Ok(())}
 fn bq086_bound(&self,actor:usize,grave_seat:usize,t:&BoundTarget,slot:&TargetSlotSpec)->RuleResult<()>{if !same(&t.spec,slot)||t.public.instance_id!=t.id||t.region_instance.is_some()||!t.public.valid||t.public.status!="valid"||t.public.invalid_reason.is_some(){return Err("BQ086原目标规格或公开绑定被改写".into());}if slot.zone==Zone::Graveyard&&(t.public.kind!="character"||t.public.label!="无名尸体"||t.public.owner!=Some(player_id(grave_seat))||t.public.controller!=Some(player_id(grave_seat))||t.public.region.is_some()){return Err("BQ086原个人墓地尸体投影不符".into());}if slot.zone==Zone::Board&&(t.public.kind!="attachment"||t.public.controller!=Some(player_id(actor))||t.public.owner.as_deref().is_none_or(|id|!(0..self.players.len()).any(|s|player_id(s)==id))||t.public.region.is_some_and(|r|r>=self.regions.len())){return Err("BQ086原本人附属投影不符".into());}if slot.zone==Zone::Player&&(t.public.kind!="player"||t.public.controller!=Some(t.id.clone())||t.public.owner.is_some()||t.public.region.is_some()){return Err("BQ086原敌方玩家投影不符".into());}if slot.zone==Zone::Player{if !t.id.strip_prefix('p').and_then(|s|s.parse::<usize>().ok()).is_some_and(|s|s<self.players.len()&&t.id==player_id(s)){return Err("BQ086原目标玩家无效".into());}}else if !self.mystic_instance_valid(&t.id){return Err("BQ086原目标实例无效".into());}Ok(())}
 pub(crate) fn validate_bq086_frame(&self,f:&ResolutionFrame)->RuleResult<()>{if !frame_related(f){return Ok(());}self.bq086_source(f.actor,&f.source)?;let mut a=definition().abilities.into_iter().find(|a|a.key==f.ability_key).ok_or("BQ086帧能力无效")?;if f.ability_key==DEATH{a.ops=f.steps.iter().map(|s|s.op.clone()).collect();self.bq086_observation(f.actor,&a.ops)?;}
  if !self.mystic_instance_valid(&f.frame_id)||f.frame_id==f.source.card.id||f.cursor>1||f.cursor==0&&!matches!(f.guard,GuardState::Unchecked)||f.cursor==1&&!matches!(f.guard,GuardState::Accepted)||!f.already_paid.is_empty()||!f.resource_payments.is_empty()||f.chosen_region.is_some()||!same(&f.steps,&a.ops.iter().map(|op|Step{context:f.actor,op:op.clone()}).collect::<Vec<_>>())||f.targets.len()!=a.targets.len(){return Err("BQ086帧原程序、完整目标或费用被改写".into());}for(t,slot)in f.targets.iter().zip(&a.targets){self.bq086_bound(f.actor,self.bq095_frozen_reference_seat(&f.source.card,&f.frame_id),t,slot)?;}if f.ability_key==DEATH{let seat=self.bq086_enemy(f)?;if self.team(seat)==self.team(f.actor){return Err("BQ086原敌方目标变为本方".into());}}else if f.targets[0].id==f.targets[1].id{return Err("BQ086墓地与附属不能绑定同一实例".into());}Ok(())
 }
 fn bq086_enemy(&self,f:&ResolutionFrame)->RuleResult<usize>{f.targets.first().and_then(|t|t.id.strip_prefix('p')).and_then(|s|s.parse::<usize>().ok()).filter(|s|*s<self.players.len()).ok_or("BQ086缺原敌方玩家".into())}
 pub(crate) fn bq086_entry_available(&self,d:&Declaration)->bool{d.source.card.definition!=ID||d.ability.key!=ENTRY||!self.binding_options(d.actor,&d.source,&d.ability.targets[1]).is_empty()}
 pub(crate) fn bq086_choose_entry(&mut self,d:Declaration,stage:DeclareChoice,selected:Vec<String>)->RuleResult<()>{self.validate_bq086_declaration(&d)?;if d.ability.key!=ENTRY{return Err("BQ086双目标选择来源无效".into());}let Some(id)=selected.first()else{return Ok(());};match stage{
  DeclareChoice::Target=>{let slot=&d.ability.targets[0];if !self.valid_binding(d.actor,&d.source,slot,id){return Err("BQ086原本人墓地尸体失效".into());}let corpse=BoundTarget{id:id.clone(),spec:slot.clone(),public:self.public_target(d.actor,&d.source,slot,id),region_instance:None};let options=self.binding_options(d.actor,&d.source,&d.ability.targets[1]);if !options.is_empty(){self.choice(d.actor,"bq086-host","选择目标本方研究附属（响应前）".into(),options,0,1,None,ChoiceResolution::Declare{declaration:d,stage:DeclareChoice::BQ086Host{corpse:Box::new(corpse)}});}Ok(())},
  DeclareChoice::BQ086Host{corpse}=>{self.bq086_bound(d.actor,self.bq095_reference_seat(&d.source.card),&corpse,&d.ability.targets[0])?;let slot=&d.ability.targets[1];if !self.valid_bound_target(d.actor,&d.source,&corpse)||!self.valid_binding(d.actor,&d.source,slot,id){return Err("BQ086双目标声明已失效".into());}let host=BoundTarget{id:id.clone(),spec:slot.clone(),public:self.public_target(d.actor,&d.source,slot,id),region_instance:None};let label=format!("{}：{}",catalog::card(ID).name,d.ability.label);let f=self.make_frame(d.actor,d.source,&d.ability,vec![*corpse,host],vec![],None);self.dispatch_frame(f,label,None,d.ability.response_policy);Ok(())},_=>Err("BQ086双目标声明阶段无效".into())}}
 fn bq086_sacrifice_options(&self,seat:usize)->Vec<ChoiceOption>{if self.players[seat].eliminated{return vec![];}self.regions.iter().enumerate().filter(|(_,r)|!r.vacant).flat_map(|(r,v)|v.cards.iter().map(move|c|(r,c))).filter(|(_,c)|c.controller==seat&&(c.face_down||catalog::card(&c.definition).kind=="character")).map(|(r,c)|self.option(c,seat,Some(r),None)).collect()}
 pub(crate) fn bq086_sacrifice(&mut self,f:ResolutionFrame)->RuleResult<()>{self.validate_bq086_frame(&f)?;let seat=self.bq086_enemy(&f)?;let options=self.bq086_sacrifice_options(seat);if !options.is_empty(){self.choice(seat,SACRIFICE,"选择自己操控的一个角色或暗藏者牺牲".into(),options,1,1,None,ChoiceResolution::Frame{frame:Box::new(f),choice:FrameChoice::BQ086Sacrifice});}Ok(())}
 pub(crate) fn bq086_finish_sacrifice(&mut self,f:ResolutionFrame,seat:usize,ids:&[String])->RuleResult<()>{self.validate_bq086_frame(&f)?;if f.ability_key!=DEATH||f.cursor!=1||seat!=self.bq086_enemy(&f)?||ids.len()!=1||!self.bq086_sacrifice_options(seat).iter().any(|o|o.id==ids[0]){return Err("BQ086只能由原敌方玩家牺牲自己的实际角色或暗藏者".into());}self.remove_dead(&ids[0],RemovalCause::Sacrifice);Ok(())}
 pub(crate) fn bq086_seal(&mut self,f:&ResolutionFrame)->RuleResult<()>{self.validate_bq086_frame(f)?;let corpse=&f.targets[0];let host=&f.targets[1];if !self.valid_bound_target(f.actor,&f.source,corpse)||!self.valid_bound_target(f.actor,&f.source,host)||!self.seal_host_valid(&host.id){return Ok(());}let c=self.bq095_take_reference(&f.source.card,&corpse.id)?;self.seal_card_on_valid_host(c,f.actor,&host.id);Ok(())}
 pub(crate) fn validate_bq086_play(&self,item:&StackItem)->RuleResult<()>{
  if !item.card.as_ref().is_some_and(|c|c.definition==ID)&&!item.frame.as_ref().is_some_and(|f|f.source.card.definition==ID&&matches!(f.ability_key.as_str(),"deploy"|"reveal")){return Ok(());}
  let f=item.frame.as_ref().ok_or("BQ086角色事务缺少原帧")?;let c=&f.source.card;
  if c.definition!=ID||f.actor>=self.players.len()||c.owner>=self.players.len()||c.controller!=f.actor||!self.mystic_instance_valid(&c.id)||!self.mystic_instance_valid(&f.frame_id)
   ||f.source.region.is_none_or(|r|r>=self.regions.len())||f.source.source_region_instance.as_deref().is_none_or(|id|!self.mystic_instance_valid(id))
   ||f.source.attachment_host_instance.is_some()||f.source.death_echo.is_some()||f.source.observed_death.is_some()||f.source.observed_exposure.is_some()||f.source.observed_mobility_grant.is_some()
   ||f.cursor!=0||!matches!(f.guard,GuardState::Unchecked)||!f.steps.is_empty()||!f.targets.is_empty()||f.chosen_region!=f.source.region
   ||!matches!(f.ability_key.as_str(),"deploy"|"reveal")||f.ability_key=="deploy"&&(c.face_down||!f.source.valid_character_play())||f.ability_key=="reveal"&&(!c.face_down||f.source.play_source.is_some())
   ||!matches!(f.already_paid.as_slice(),[PaidCost::Assets(ids)] if f.money_units(0)<=6&&ids.iter().all(|id|self.mystic_instance_valid(id)&&*id!=c.id)&&ids.iter().collect::<BTreeSet<_>>().len()==ids.len())
   ||item.id!=f.frame_id||item.controller!=f.actor||item.target.is_some()||item.reveal!=(f.ability_key=="reveal")||item.deploy_region!=f.source.region
   ||item.card.as_ref().is_none_or(|c|!self.pack_a_transaction_matches(f,c)){return Err("BQ086角色事务、原帧或实际牌面不符".into());}self.mobility_immutable_identity(c)
 }

 pub(crate) fn validate_bq086_state(&self)->RuleResult<()>{
  let mut frames=BTreeSet::new();let mut events=BTreeSet::new();let mut remember=|s:&SourceSnapshot,ops:&[Op]|->RuleResult<()>{if matches!(ops,[Op::BQ086Seal])&&!events.insert((s.card.id.clone(),"entry".into())){return Err("BQ086同一进场声明重复携带".into());}if let [Op::BQ086Death{observation:Some(o)}]=ops{if !events.insert((s.card.id.clone(),o.event_id.clone())){return Err("BQ086同一死亡观察重复消费".into());}}Ok(())};
  for item in &self.stack{self.validate_bq086_play(item)?;if let Some(f)=&item.frame{if frame_related(f){self.validate_bq086_frame(f)?;remember(&f.source,&f.steps.iter().map(|s|s.op.clone()).collect::<Vec<_>>())?;if !frames.insert(&f.frame_id)||item.id!=f.frame_id||item.controller!=f.actor||item.card.is_some()||item.reveal||item.deploy_region.is_some()||item.target!=f.targets.first().map(|t|t.id.clone())||f.cursor!=0{return Err("BQ086响应外壳或唯一原帧不符".into());}}}}
  for e in &self.effects{match e{Effect::Declare{declaration:d}if related(&d.ability)=>{self.validate_bq086_declaration(d)?;remember(&d.source,&d.ability.ops)?;},Effect::Frame{frame}if frame_related(frame)=>return Err("BQ086不允许伪造独立执行续体".into()),_=>()}}
  if let Some(p)=&self.pending{match &p.resolution{
   ChoiceResolution::Declare{declaration:d,stage}if related(&d.ability)||matches!(stage,DeclareChoice::BQ086Host{..})=>{self.validate_bq086_declaration(d)?;remember(&d.source,&d.ability.ops)?;
    let(options,kind,title)=match stage{DeclareChoice::Target=>(self.binding_options(d.actor,&d.source,&d.ability.targets[0]),"trigger",format!("{}：{}",crate::batch3_trap::source_label(&d.source),d.ability.label)),DeclareChoice::BQ086Host{corpse}if d.ability.key==ENTRY=>{self.bq086_bound(d.actor,self.bq095_reference_seat(&d.source.card),corpse,&d.ability.targets[0])?;if !self.valid_bound_target(d.actor,&d.source,corpse)||!same(&corpse.public,&self.public_target(d.actor,&d.source,&corpse.spec,&corpse.id)){return Err("BQ086响应前原尸体绑定失效或改写".into());}(self.binding_options(d.actor,&d.source,&d.ability.targets[1]),"bq086-host","选择目标本方研究附属（响应前）".into())},_=>return Err("BQ086声明阶段无效".into())};
    let expected=Choice{id:p.choice.id.clone(),kind:kind.into(),title,description:"选择符合数量限制的选项，然后确认。".into(),player_id:player_id(d.actor),options,preview_cards:vec![],min:Some(0),max:Some(1),amount:None,allow_decline:Some(true)};if p.seat!=d.actor||!self.mystic_instance_valid(&p.choice.id)||expected.options.is_empty()||!same(&p.choice,&expected){return Err("BQ086声明选项或选择者被改写".into());}},
   ChoiceResolution::Frame{frame:f,choice}if frame_related(f)||matches!(choice,FrameChoice::BQ086Sacrifice)=>{self.validate_bq086_frame(f)?;remember(&f.source,&f.steps.iter().map(|s|s.op.clone()).collect::<Vec<_>>())?;let seat=self.bq086_enemy(f)?;let expected=Choice{id:p.choice.id.clone(),kind:SACRIFICE.into(),title:"选择自己操控的一个角色或暗藏者牺牲".into(),description:"选择符合数量限制的选项，然后确认。".into(),player_id:player_id(seat),options:self.bq086_sacrifice_options(seat),preview_cards:vec![],min:Some(1),max:Some(1),amount:None,allow_decline:Some(false)};if !frames.insert(&f.frame_id)||!matches!(choice,FrameChoice::BQ086Sacrifice)||f.ability_key!=DEATH||f.cursor!=1||p.seat!=seat||!self.mystic_instance_valid(&p.choice.id)||expected.options.is_empty()||!same(&p.choice,&expected){return Err("BQ086牺牲待选、原帧或唯一载体不符".into());}},_=>()
  }}Ok(())
 }
}
